 const auditLabels={useStatus:'USE',useCampaign:'Campaign / ad name',productsShown:'Products shown',postingByAccount:'Posting by account',contentKind:'Content format',title:'Video name',accounts:'Account',type:'Video type',model:'Model',shootDate:'Shoot date',editedDate:'Edited date',shotBy:'Shot by',editedBy:'Edited by',editStatus:'Editing',postingStatus:'Posting',rawUrl:'Raw file link',finalUrl:'Final file link',archived:'Deleted',deletionApproval:'Deletion approval',productIds:'Products',adIds:'Ads',shooter:'Shooter assigned',editor:'Editor assigned',publisher:'Posting owner',notes:'Notes',dueDate:'Due date',shootStatus:'Shoot status',contentFormat:'Format',shootId:'Shoot booking',adCreative:'Ad creative'};
 function auditValue(v){if(v===null||v===''||v===undefined)return '—';if(Array.isArray(v))return v.join(', ')||'—';if(typeof v==='object')return Object.entries(v).map(([a,status])=>a+': '+auditValue(status)).join(', ');if(typeof v==='boolean')return v?'Yes':'No';return ({not_used:'Not used',active:'Active',previously_used:'Previously used',done:'Edited',pending:'Not edited',editing:'Editing',not_posted:'Not posted',posted:'Posted'})[v]||String(v);}
 function auditTime(v){return v?new Date(v).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',dateStyle:'medium',timeStyle:'short'}):'Not recorded';}
 async function openRowHistory(id){if(!state.permissions.manage)return;try{const d=await api('/items/'+encodeURIComponent(id)+'/history'),i=d.item;let dialog=$('rowHistoryDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='rowHistoryDialog';document.body.append(dialog);}dialog.innerHTML='<div class="history-heading"><h2>Row history</h2><button data-close>Close</button></div><h3>'+e(i.title)+'</h3><p><strong>'+(i.imported?'Added to app':'Created by')+':</strong> '+e(name(i.createdBy)||'Not recorded')+' · '+e(auditTime(i.createdAt))+'</p><p><strong>Last saved by:</strong> '+e(name(i.updatedBy)||'Not recorded')+' · '+e(auditTime(i.updatedAt))+'</p><p class="muted">Older records may not include their creator or detailed changes. Sheet imports show who added the entry to this app.</p><div class="table-wrap"><table class="row-history-table"><thead><tr><th>When</th><th>Who</th><th>Change</th></tr></thead><tbody>'+ (d.events.map(h=>'<tr><td>'+e(auditTime(h.at))+'</td><td>'+e(h.actor==='Google Sheet sync'?h.actor:name(h.actor))+'</td><td><strong>'+e(h.action==='create'?'Entry added':h.action.replaceAll('_',' ').replaceAll('-',' '))+'</strong>'+ (h.changes.length?'<details '+(h.changes.length<4?'open':'')+'><summary>'+h.changes.length+(h.changes.length===1?' field':' fields')+'</summary>'+h.changes.map(c=>'<p><strong>'+e(auditLabels[c.field]||c.field)+':</strong> '+e(auditValue(c.before))+' → '+e(auditValue(c.after))+'</p>').join('')+'</details>':'<p class="muted">Field details were not recorded for this older update.</p>')+'</td></tr>').join('')||'<tr><td colspan="3">No changes recorded yet.</td></tr>')+'</tbody></table></div>';dialog.showModal();}catch(err){message(err.message,true);}}
