 function recordPoaOutput(t){let d=$('poaRawDialog');if(!d){d=document.createElement('dialog');d.id='poaRawDialog';document.body.append(d);}d.innerHTML='<form id="poaRawForm"><header><h2>Add raw link</h2><button type="button" data-close>Close</button></header><p>'+e(t.title)+' · '+e(t.accounts.join(' / '))+'</p><label>Content name<input name="title" maxlength="200" required value="'+e(t.title+' '+(t.progress.linked+1))+'"></label><label>Shoot date<input name="shootDate" type="date" required value="'+e(state.today)+'"></label><label>Raw video / folder link<input name="rawUrl" type="url" required placeholder="https://drive.google.com/…"></label><p class="muted">Saving adds the same entry to '+(t.contentKind==='story'?'Stories':'Videos / Reels')+'. Products, cast and assignments come from this POA.</p><p class="error" role="alert"></p><button type="submit" class="primary">Save raw link</button></form>';const f=$('poaRawForm');f.onsubmit=async ev=>{ev.preventDefault();if(busy)return;busy=true;const btn=f.querySelector('[type=submit]');btn.disabled=true;try{await approvalSave('/items',{poaId:t.id,title:f.elements.title.value,shootDate:f.elements.shootDate.value,rawUrl:f.elements.rawUrl.value,shootStatus:'shot',editStatus:'pending',adIds:[]});d.close();await load();}catch(err){f.querySelector('.error').textContent=err.message;}finally{busy=false;btn.disabled=false;}};d.showModal();}

 document.addEventListener('poa-changed',()=>load());
 function openItem(id='',account='',due=''){poaTarget='';const i=item(id),f=$('itemForm');f.reset();f.querySelector('.error').textContent='';$('itemTitle').textContent=i?'Edit content':'Add content';f.elements.id.value=id;$('itemType').innerHTML=types.map(t=>'<option>'+e(t)+'</option>').join('');$('accounts').innerHTML=['Femme','Homme','Fashion'].map(a=>'<label><input type="checkbox" name="account" value="'+a+'" '+((i?.accounts||[account]).includes(a)?'checked':'')+'>'+a+'</label>').join('');for(const n of ['shooter','editor','publisher'])f.elements[n].innerHTML=peopleOptions(i?.[n]||state.settings.accounts.find(a=>a.account===account)?.[n]||'');$('shootChoice').innerHTML='<option value="">No linked booking</option>'+shoots.map(s=>'<option value="'+e(s.id)+'">'+e(s.date)+' · '+e(name(s.model))+' · '+e(s.status)+'</option>').join('');for(const n of ['shotBy','editedBy'])f.elements[n].innerHTML=teamChoices(i?.[n],n==='editedBy').map(([v,label])=>'<option value="'+e(v)+'">'+e(label)+'</option>').join('');for(const key of ['title','type','model','shootDate','editedDate','shotBy','editedBy','dueDate','shootStatus','editStatus','rawUrl','finalUrl','notes','shootId'])if(i)f.elements[key].value=['model','shotBy','editedBy'].includes(key)?name(i[key]):i[key]||'';$('modalPosting').innerHTML=postingEditor(i,i?.accounts||[account].filter(Boolean),'modalPosting','itemForm');f.elements.productsShown.value=i?.productsShown||'';if(!i)f.elements.dueDate.value=due;f.elements.adCreative.checked=!!i?.adCreative;selected=new Set(i?.productIds||[]);adSelection=new Set(i?.adIds||[]);$('adLinks').hidden=!state.permissions.results;$('productSearch').value='';$('adSearch').value='';productOptions();selectedProducts();adOptions();$('itemDialog').showModal();applyFinalRules(true);}
 $('itemForm').onsubmit=ev=>{ev.preventDefault();const f=ev.currentTarget,b={};for(const k of ['title','type','model','shootDate','editedDate','shotBy','editedBy','productsShown','dueDate','shootStatus','editStatus','shooter','editor','publisher','rawUrl','finalUrl','notes','shootId'])b[k]=f.elements[k].value;b.poaId=f.elements.id.value?item(f.elements.id.value)?.poaId||'':poaTarget;b.contentKind=f.elements.id.value?workflow.contentKind(item(f.elements.id.value)):contentKind;b.accounts=[...f.querySelectorAll('[name="account"]:checked')].map(x=>x.value);b.postingByAccount=readPosting(f,'modalPosting',b.accounts);b.productIds=[...selected];b.adIds=[...adSelection];b.adCreative=f.elements.adCreative.checked;mutate('/items'+(f.elements.id.value?'/'+f.elements.id.value:''),b,f.elements.id.value?'PATCH':'POST',$('itemDialog'));};
 function openPost(id,account='',slotId=''){const i=item(id),f=$('postForm');f.reset();f.querySelector('.error').textContent='';postTarget={contentId:id,slotId};$('postName').textContent='#'+i.entryNumber+' · '+i.title;$('postingFile').innerHTML=i.finalUrl?'<a target="_blank" rel="noopener noreferrer" href="'+e(i.finalUrl)+'">Open final video ↗</a>':'';f.elements.account.innerHTML=i.accounts.filter(a=>!workflow.isPosted(i,state.publications,a)).map(a=>'<option>'+a+'</option>').join('');if(account)f.elements.account.value=account;f.elements.date.value=state.today;f.elements.date.max=state.today;$('postDialog').showModal();}
 $('postForm').onsubmit=ev=>{ev.preventDefault();const f=ev.currentTarget;mutate('/posted',{...postTarget,account:f.elements.account.value,date:f.elements.date.value,url:f.elements.url.value,checks:[...f.querySelectorAll('[name=postingCheck]:checked')].map(el=>el.value)},'POST',$('postDialog'));};
 function openTask(id,stage,account,slot){if(stage==='post')return openPost(id,account,slot);const i=item(id),f=$('taskForm');taskTarget={id,stage};f.reset();f.querySelector('.error').textContent='';$('taskTitle').textContent=stage==='shoot'?'Update shoot':'Update editing';$('taskName').textContent=i.title;$('taskLinkLabel').firstChild.textContent=stage==='shoot'?'Raw footage link':'Final file link';f.elements.url.value=stage==='shoot'?i.rawUrl:i.finalUrl;f.elements.status.innerHTML=(stage==='shoot'?[['planned','To shoot'],['shot','Shot']]:[['pending','Pending'],['editing','Editing'],['done','Done']]).map(([v,n])=>'<option value="'+v+'">'+n+'</option>').join('');f.elements.status.value=stage==='shoot'?i.shootStatus:i.editStatus;$('taskDialog').showModal();}
 $('taskForm').onsubmit=ev=>{ev.preventDefault();const f=ev.currentTarget,b=taskTarget.stage==='shoot'?{shootStatus:f.elements.status.value,rawUrl:f.elements.url.value}:{editStatus:f.elements.status.value,finalUrl:f.elements.url.value};mutate('/items/'+taskTarget.id,b,'PATCH',$('taskDialog'));};
 $('settings').onclick=()=>{const f=$('planForm'),s=state.settings;f.querySelector('.error').textContent='';for(const k of ['start','days','buffer','editLead','shootLead'])f.elements[k].value=s[k];$('planAccounts').innerHTML=s.accounts.map((a,i)=>'<fieldset><legend>'+e(a.account)+'</legend><div class="two"><label>Videos per day<input type="number" name="daily'+i+'" min="0" max="5" value="'+a.daily+'" required></label><label>Stories per day<input type="number" name="storyDaily'+i+'" min="0" max="20" value="'+(a.storyDaily||0)+'" required></label>'+['shooter','editor','publisher'].map(k=>'<label>'+({shooter:'Shoot owner',editor:'Editor',publisher:'Posting owner'}[k])+'<select name="'+k+i+'">'+peopleOptions(a[k])+'</select></label>').join('')+'</div></fieldset>').join('');$('planDialog').showModal();};
 $('planForm').onsubmit=ev=>{ev.preventDefault();const f=ev.currentTarget,s={start:f.elements.start.value};for(const k of ['days','buffer','editLead','shootLead'])s[k]=Number(f.elements[k].value);s.accounts=['Femme','Homme','Fashion'].map((account,i)=>({account,daily:Number(f.elements['daily'+i].value),storyDaily:Number(f.elements['storyDaily'+i].value),...Object.fromEntries(['shooter','editor','publisher'].map(k=>[k,f.elements[k+i].value]))}));mutate('/settings',{settings:s},'POST',$('planDialog'));};
 document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(document.querySelector('[data-ops-dirty=true]')&&(b.dataset.kind||b.dataset.poaMode||b.dataset.view)){message('Save your checklist note before switching views.',true);return;}if(b.dataset.contentUse){if(state.permissions.use)openUse(item(b.dataset.contentUse));return;}if(b.dataset.productsKind==='content'){const i=item(b.dataset.productsId);if(i)window.ContentPOA.showProducts(i);return;}if(b.dataset.openPoa){clearContentDates();planContext().openPoa(b.dataset.openPoa);return;}if(b.dataset.poaMode){if(editingRow){message('Save or cancel your current row first.',true);return;}$('view').value=b.dataset.poaMode;render();return;}if(b.dataset.kind){if(editingRow){message('Save or cancel your current row before switching.',true);return;}contentKind=b.dataset.kind;if(['poa','tasks','dailycheck'].includes($('view').value))$('view').value='content';activityOpen=null;for(const id of ['account','type','model','search','editorFilter'])$(id).value='';$('show').value='all';modelOptions();render();return;}if(b.dataset.rowHistory){openRowHistory(b.dataset.rowHistory);return;}if(b.dataset.delete){const i=item(b.dataset.delete);if(!i||!state.permissions.edit)return;const f=$('deleteForm');f.reset();f.elements.contentId.value=i.id;$('deleteTitle').textContent=i.title;f.querySelector('.error').textContent='';$('deleteDialog').showModal();return;}if(b.dataset.deleteDecision){queueAction('/delete-requests/'+b.dataset.request+'/decision',{decision:b.dataset.deleteDecision});return;}if(b.dataset.deleteRestore){queueAction('/items/'+b.dataset.deleteRestore+'/archive',{archived:false});return;}if(b.hasAttribute('data-editor')){if(!state.permissions.manage)return;$('editorFilter').value=b.dataset.editor;render();return;}if(b.hasAttribute('data-activity-person')){const next={person:b.dataset.activityPerson,metric:b.dataset.activityMetric};activityOpen=activityOpen?.person===next.person&&activityOpen?.metric===next.metric?null:next;render();return;}if(b.dataset.rowEdit){startRow(b.dataset.rowEdit);return;}if(b.id==='cancelRow'){editingRow='';$('rowError').textContent='';render();return;}if(b.hasAttribute('data-model-tab')){if(editingRow){message('Save or cancel your current row first.',true);return;}$('model').value=b.dataset.modelTab;$('search').value='';if(!['edit','posted','all','post'].includes($('show').value))$('show').value='post';$('view').value='content';render();return;}if(b.hasAttribute('data-type-tab')){if(editingRow){message('Save or cancel your current row first.',true);return;}$('type').value=b.dataset.typeTab;$('model').value='';$('search').value='';if(!['edit','posted','all','post'].includes($('show').value))$('show').value='post';$('view').value='content';render();return;}if(b.hasAttribute('data-account-tab')){if(editingRow){message('Save or cancel your current row first.',true);return;}$('account').value=b.dataset.accountTab;$('model').value='';render();return;}if(b.dataset.view){$('view').value=b.dataset.view;render();return;}if(b.dataset.expand){const panel=$('detail-'+b.dataset.expand);panel.hidden=!panel.hidden;b.setAttribute('aria-expanded',String(!panel.hidden));return;}if(b.hasAttribute('data-close'))return b.closest('dialog').close();if(b.id==='planShoot'){openItem('',$('account').value);$('itemForm').elements.shootDate.value=state.today;$('itemTitle').textContent='Plan shoot';}if(b.dataset.edit)openItem(b.dataset.edit);if(b.dataset.brief)openItem('',b.dataset.brief,b.dataset.date);if(b.dataset.product){selected.add(b.dataset.product);selectedProducts();productOptions();}if(b.dataset.removeProduct){selected.delete(b.dataset.removeProduct);selectedProducts();productOptions();}if(b.dataset.task)openTask(b.dataset.task,b.dataset.stage,b.dataset.account,b.dataset.slot);if(b.dataset.filter){$('model').value='';if(b.dataset.filter==='calendar'){$('view').value='calendar';$('show').value='all';}else{$('view').value='content';$('show').value=b.dataset.filter;}render();}});
