 document.addEventListener('change',ev=>{if(ev.target.name!=='editStatus'||ev.target.value!=='done')return;const form=ev.target.form,old=ev.target.getAttribute('form')==='rowForm'?item(editingRow):item($('itemForm').elements.id.value);if(form&&old?.editStatus!=='done')form.elements.editedDate.value=state.today;});
