 let importFile,importRevision;
 async function importRequest(preview){const data=new FormData();data.append('file',importFile);data.append('preview',String(preview));data.append('confirmed',String(!preview));data.append('revision',String(importRevision));const r=await fetch('/api/content-production/import',{method:'POST',body:data});const d=await r.json();if(!r.ok||!d.success)throw Error(d.error||'Import failed.');return d;}
 $('importOpen').onclick=()=>$('importFile').click();$('importFile').onchange=async ev=>{importFile=ev.target.files[0];if(!importFile)return;importRevision=state.revision;try{const d=await importRequest(true);$('importPreview').innerHTML='<h3>'+d.count+' new · '+d.updated+' to update · '+d.unchanged+' unchanged</h3><p>Excluded tabs: '+e(d.ignoredTabs.join(', '))+'</p><details><summary>Review imported records</summary><div class="picker">'+d.records.map(x=>'<p>'+e(x.action)+' · '+e(x.source.tab)+' '+x.source.row+' · '+e(x.title)+' · '+e(x.editStatus)+'</p>').join('')+'</div></details>'+d.warnings.map(w=>'<p class="warning">'+e(w)+'</p>').join('');$('importConfirm').disabled=!(d.count+d.updated);$('importDialog').querySelector('.error').textContent='';$('importDialog').showModal();}catch(err){message(err.message,true);}};
 $('importConfirm').onclick=async()=>{if(busy)return;busy=true;$('importConfirm').disabled=true;try{await importRequest(false);$('importDialog').close();await load();}catch(err){$('importDialog').querySelector('.error').textContent=err.message;}finally{busy=false;$('importConfirm').disabled=false;}};
