 $('addEditorForm').onsubmit=async ev=>{ev.preventDefault();if(busy||!state.permissions.manage)return;const added=name($('newEditorName').value);if(!added)return;busy=true;const button=ev.currentTarget.querySelector('[type="submit"]');button.disabled=true;try{await api('/editors','POST',{revision:state.revision,names:[...new Set([...state.editorNames,added])]});$('addEditorDialog').close();await load();$('editorFilter').value=added.toLowerCase();render();message('Editor added: '+added);}catch(err){$('addEditorDialog').querySelector('.error').textContent=err.message;}finally{busy=false;button.disabled=false;}};
